$f=supportFixture();extract($f);$dep=$departments[0];$target=$departments[1];
$env=array_replace(getenv(),['APP_ENV'=>'test','APP_URL'=>$config->url,'APP_KEY'=>$config->key,'DB_DSN'=>$config->dsn,'DB_USER'=>$config->dbUser,'DB_PASSWORD'=>$config->dbPassword,'PROVISIONING_ALLOWED'=>'false','PAYMENT_LIVE_ALLOWED'=>'false','EXTERNAL_MAIL_ALLOWED'=>'false','HTTP_TEST_ENGINE'=>'interpreter']);
$server=new HttpTestServer(dirname(__DIR__),$env,__DIR__.'/commerce-router.php');$second=new HttpTestServer(dirname(__DIR__),$env,__DIR__.'/commerce-router.php');$jars=['client'=>[],'admin'=>[]];$tokens=['client'=>'','admin'=>''];$examples=[];
function sh(string $ctx,string $route,?array $body=null,?string $key=null,bool $csrf=true,?string $method=null): array
{
    global $server,$jars,$tokens;$options=[];
    if($jars[$ctx]){$options[CURLOPT_COOKIE]=implode('; ',array_map(fn($k,$v)=>$k.'='.$v,array_keys($jars[$ctx]),$jars[$ctx]));}
    if($body!==null){$h=['Content-Type: application/json','Idempotency-Key: '.($key??Id::uuid())];if($csrf){$h[]='X-CSRF-Token: '.$tokens[$ctx];}$options+=[CURLOPT_POST=>true,CURLOPT_POSTFIELDS=>json_encode((object)$body,JSON_THROW_ON_ERROR),CURLOPT_HTTPHEADER=>$h];}if($method){$options[CURLOPT_CUSTOMREQUEST]=$method;}
    [$status,$raw,$headers]=$server->request('/api/v1/'.$ctx.'/'.$route,$options);foreach($headers as $header){if(preg_match('/^Set-Cookie: ([^=]+)=([^;]*)/i',$header,$m)){$jars[$ctx][$m[1]]=$m[2];}}$r=json_decode($raw,true);if(isset($r['data']['csrf'])){$tokens[$ctx]=$r['data']['csrf'];}return [$status,$r,$raw,$headers];
}
function st(?string $department=null,array $extra=[]): array
{
    global $dep;$r=sh('client','support/create',array_replace(['department_id'=>$department??$dep,'subject'=>'Synthetic ticket','body'=>'Public initial message','priority'=>'NORMAL'],$extra));same(200,$r[0]);return $r[1]['data'];
}
function sd(array $t,string $ctx='client'): array{return sh($ctx,'support/detail?id='.$t['id']);}
function sr(array $t,string $ctx='admin',string $route='reply',array $extra=[],?string $key=null): array{return sh($ctx,'support/'.$route,array_replace(['id'=>$t['id'],'version'=>$t['version'],'body'=>'Synthetic reply'],$extra),$key);}
function supportParallel(array $t,bool $sameKey=false,int $workers=2,bool $distinctStaff=false): array
{
    global $server,$second,$jars,$tokens,$env;$children=[];$key=Id::uuid();$cookie=implode('; ',array_map(fn($k,$v)=>$k.'='.$v,array_keys($jars['admin']),$jars['admin']));
    for($n=0;$n<$workers;++$n){$srv=$n%2===0?$server:$second;$auth=$distinctStaff&&$n%2===1?$GLOBALS['secondStaffAuth']:['cookie'=>$cookie,'csrf'=>$tokens['admin']];$pipes=[];$p=proc_open([PHP_BINARY,__DIR__.'/support-http-child.php'],[0=>['pipe','r'],1=>['pipe','w'],2=>['pipe','w']],$pipes,null,$env);if(!is_resource($p)){throw new RuntimeException('Child unavailable');}fwrite($pipes[0],json_encode(['url'=>'http://127.0.0.1:'.$srv->diagnostics()['port'].'/api/v1/admin/support/reply','body'=>['id'=>$t['id'],'version'=>$t['version'],'body'=>'Concurrent public reply'],'key'=>$sameKey?$key:Id::uuid(),'cookie'=>$auth['cookie'],'csrf'=>$auth['csrf']],JSON_THROW_ON_ERROR));fclose($pipes[0]);$children[]=[$p,$pipes];}
    $out=[];$bad=false;foreach($children as [$p,$pipes]){$raw=stream_get_contents($pipes[1]);$err=stream_get_contents($pipes[2]);fclose($pipes[1]);fclose($pipes[2]);$exit=proc_close($p);$bad=$bad||$exit!==0||$err!=='';$out[]=json_decode($raw,true,32,JSON_THROW_ON_ERROR);}same(false,$bad);return $out;
}
function supportLogin(string $ctx,array $who): void
{
    sh($ctx,'identity/bootstrap');same(200,sh($ctx,'identity/login',['email'=>$who['email'],'password'=>$who['password']])[0]);
    if($ctx==='admin'){same(403,sh($ctx,'support/list')[0]);same(200,sh($ctx,'identity/mfa',['code'=>$who['recovery'][0]])[0]);same(200,sh($ctx,'identity/step-up',['password'=>$who['password'],'code'=>$who['recovery'][1]])[0]);}
}
