test('F5-A explicit department reopen policy changes permit only canonical transition',function()use($dep,$db): void{$t=st();same(200,sh('admin','support/state',['id'=>$t['id'],'version'=>1,'status'=>'CLOSED'])[0]);$d=$db->execute('SELECT * FROM support_departments WHERE id=?',[$dep])->fetch();$p=['id'=>$dep,'version'=>(int)$d['version'],'name'=>$d['name'],'enabled'=>true,'allow_reopen'=>true,'allow_hold'=>true];same(200,sh('admin','support/department',$p)[0]);same(200,sr(array_replace($t,['version'=>2]),'client')[0]);same('WAITING_STAFF',sd($t)[1]['data']['status']);same(200,sh('admin','support/state',['id'=>$t['id'],'version'=>3,'status'=>'ON_HOLD'])[0]);$p['version']++;$p['allow_reopen']=false;$p['allow_hold']=false;same(200,sh('admin','support/department',$p)[0]);});
test('F5-A native staff removal revokes department membership without deleting history',function()use($db,$c,$admin,$dep): void{$t=st();$who=$GLOBALS['secondStaffUser'];$saved=$GLOBALS['jars']['admin'];$token=$GLOBALS['tokens']['admin'];$GLOBALS['jars']['admin']=$GLOBALS['secondStaffJar'];$GLOBALS['tokens']['admin']=$GLOBALS['secondStaffAuth']['csrf'];try{same(200,sd($t,'admin')[0]);$before=supportCounts($db);$c->identity->staff($admin['reference'],'admin',$who['user'],false,false);same(0,(int)$db->execute('SELECT COUNT(*) FROM support_department_members WHERE user_id=?',[$who['user']])->fetchColumn());same(401,sd($t,'admin')[0]);same($before['support_messages'],supportCounts($db)['support_messages']);}finally{$GLOBALS['jars']['admin']=$saved;$GLOBALS['tokens']['admin']=$token;}});
test('F5-A requester membership revocation succeeds and keeps immutable ticket history',function()use($db,$other,$service): void{$saved=$GLOBALS['jars']['client'];$token=$GLOBALS['tokens']['client'];$GLOBALS['jars']['client']=[];$GLOBALS['tokens']['client']='';try{supportLogin('client',$other);$t=st();$db->execute('DELETE FROM identity_memberships WHERE user_id=? AND customer_id=?',[$other['user'],$other['customer']]);same(403,sd($t)[0]);same(1,(int)$db->execute('SELECT COUNT(*) FROM support_messages WHERE ticket_id=?',[$t['id']])->fetchColumn());}finally{$GLOBALS['jars']['client']=$saved;$GLOBALS['tokens']['client']=$token;}});
test('F5-A identity version invalidation rejects next HTTP request',function()use($db,$client): void{$db->execute('UPDATE identity_users SET identity_version=identity_version+1 WHERE id=?',[$client['user']]);same(401,sh('client','support/list')[0]);});
test('F5-A session revocation rejects read and cached mutation',function()use($db,$admin): void{$db->execute("UPDATE identity_sessions SET revoked_at=UTC_TIMESTAMP(6) WHERE user_id=? AND context='admin'",[$admin['user']]);same(401,sh('admin','support/list')[0]);same(401,sh('admin','support/department-new',['name'=>'Denied','enabled'=>true,'allow_reopen'=>false,'allow_hold'=>false])[0]);});
$exit=executeTests(true);
if($exit===0&&getenv('F5_EVIDENCE')==='1'){file_put_contents(dirname(__DIR__).'/docs/evidence/f5-a/http-examples.json',json_encode(['environment'=>'test','synthetic'=>true,'provider_io'=>false,'examples'=>$examples],JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR));}
}finally{$server->stop();$second->stop();}
exit($exit);
